import pandas as pd
import networkx as nx

companies = pd.read_csv('/app/dataset/companies.csv')
invoices = pd.read_csv('/app/dataset/invoices.csv')

# Build a directed graph from invoices
G = nx.DiGraph()
for idx, row in invoices.iterrows():
    s = int(row['seller_id'])
    b = int(row['buyer_id'])
    w = float(row['gross_amount'])
    if G.has_edge(s, b):
        G[s][b]['weight'] += w
        G[s][b]['count'] += 1
    else:
        G.add_edge(s, b, weight=w, count=1)

# Let's find cycles or chains involving our 13 key suspects
suspects = {4612, 8382, 3495, 8285, 8770, 7021, 4521, 1060, 8810, 3554, 2950, 1967, 5765}

# Find all simple cycles in G
cycles = list(nx.simple_cycles(G))
print(f"Total simple cycles found in the entire invoice network: {len(cycles)}")

# Print cycles involving any of our suspects
sus_cycles = [c for c in cycles if any(node in suspects for node in c)]
print(f"Cycles involving suspects: {len(sus_cycles)}")
for i, c in enumerate(sus_cycles):
    print(f"Cycle {i+1}: {c}")

# Let's inspect paths from Benford sellers (4612, 8382) to our suspects
for src in [4612, 8382]:
    for dest in suspects:
        if src != dest:
            if nx.has_path(G, src, dest):
                paths = list(nx.all_simple_paths(G, src, dest, cutoff=3))
                if len(paths) > 0:
                    print(f"Path from Benford seller {src} to suspect {dest}:")
                    for p in paths[:3]:
                        # print path with edge weights
                        path_str = []
                        for u, v in zip(p[:-1], p[1:]):
                            path_str.append(f"{u} -[val={G[u][v]['weight']:.2f}, cnt={G[u][v]['count']}]-> {v}")
                        print("  " + " | ".join(path_str))

