import pandas as pd
from collections import defaultdict

companies = pd.read_csv('/app/dataset/companies.csv')
invoices = pd.read_csv('/app/dataset/invoices.csv')

# Build graph as dict of dicts: adj[u][v] = { 'weight': w, 'count': c }
adj = defaultdict(dict)
for idx, row in invoices.iterrows():
    s = int(row['seller_id'])
    b = int(row['buyer_id'])
    w = float(row['gross_amount'])
    if b in adj[s]:
        adj[s][b]['weight'] += w
        adj[s][b]['count'] += 1
    else:
        adj[s][b] = {'weight': w, 'count': 1}

# 1. Manual Cycle Finding
# Find simple cycles using DFS
visited = {}
cycles = []

def find_cycles(node, path):
    visited[node] = 1 # Active
    path.append(node)
    for neighbor in adj[node]:
        if visited.get(neighbor, 0) == 1:
            # Cycle found!
            cycle_start_idx = path.index(neighbor)
            cycles.append(path[cycle_start_idx:])
        elif visited.get(neighbor, 0) == 0:
            find_cycles(neighbor, path)
    path.pop()
    visited[node] = 2 # Completed

# Initialize cycle finding for all nodes
for node in list(adj.keys()):
    if visited.get(node, 0) == 0:
        find_cycles(node, [])

print(f"Total simple cycles found: {len(cycles)}")

suspects = {4612, 8382, 3495, 8285, 8770, 7021, 4521, 1060, 8810, 3554, 2950, 1967, 5765}
sus_cycles = [c for c in cycles if any(node in suspects for node in c)]
print(f"Cycles involving suspects: {len(sus_cycles)}")
for i, c in enumerate(sus_cycles):
    print(f"Cycle {i+1}: {c}")

# 2. Path Finding from 4612 and 8382 to suspects
def find_paths_cutoff(src, dest, max_len=3):
    paths = []
    def dfs(curr, target, path):
        if len(path) > max_len:
            return
        if curr == target:
            paths.append(list(path))
            return
        for neighbor in adj[curr]:
            if neighbor not in path:
                path.append(neighbor)
                dfs(neighbor, target, path)
                path.pop()
    dfs(src, dest, [src])
    return paths

print("\n--- Paths from Benford Deviators (4612, 8382) to suspects ---")
for src in [4612, 8382]:
    for dest in suspects:
        if src != dest:
            paths = find_paths_cutoff(src, dest, max_len=3)
            if len(paths) > 0:
                print(f"Path from {src} to {dest}:")
                for p in paths[:3]:
                    path_str = []
                    for u, v in zip(p[:-1], p[1:]):
                        path_str.append(f"{u} -[val={adj[u][v]['weight']:.2f}, cnt={adj[u][v]['count']}]-> {v}")
                    print("  " + " | ".join(path_str))

